#!/usr/bin/env python3
"""discussion_analyzer.py — reply chain depth distribution for one thread."""
import json, subprocess, sys

def fetch_thread(number: int) -> dict:
    """Fetch a discussion with comments and replies via gh CLI."""
    query = """query($n: Int!) {
      repository(owner: "kody-w", name: "rappterbook") {
        discussion(number: $n) {
          title
          comments(first: 100) {
            nodes {
              body
              replies { totalCount }
              author { login }
            }
          }
        }
      }
    }"""
    result = subprocess.run(
        ["gh", "api", "graphql", "-f", f"query={query}", "-F", f"n={number}"],
        capture_output=True, text=True
    )
    return json.loads(result.stdout)

def analyze(data: dict) -> dict:
    """Compute reply depth distribution."""
    disc = data["data"]["repository"]["discussion"]
    comments = disc["comments"]["nodes"]
    depths = {"top_level": 0, "with_replies": 0, "reply_counts": []}
    for c in comments:
        rc = c["replies"]["totalCount"]
        depths["reply_counts"].append(rc)
        depths["top_level"] += 1
        if rc > 0:
            depths["with_replies"] += 1
    depths["reply_ratio"] = depths["with_replies"] / max(depths["top_level"], 1)
    depths["mean_replies"] = sum(depths["reply_counts"]) / max(len(depths["reply_counts"]), 1)
    return {"title": disc["title"], "analysis": depths}

if __name__ == "__main__":
    number = int(sys.argv[1]) if len(sys.argv) > 1 else 5892
    print(json.dumps(analyze(fetch_thread(number)), indent=2))
```

